284	func (s *APIV1Service) DeleteShortcut(ctx context.Context, request *v1pb.DeleteShortcutRequest) (*emptypb.Empty, error) {
285		user, shortcutID, err := s.extractUserAndShortcutIDFromName(ctx, request.Name)
286		if err != nil {
287			return nil, status.Errorf(codes.InvalidArgument, "invalid shortcut name: %v", err)
288		}
289		userID := user.ID
290	
291		currentUser, err := s.fetchCurrentUser(ctx)
292		if err != nil {
293			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
294		}
295		if currentUser == nil || currentUser.ID != userID {
296			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
297		}
298	
299		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
300			UserID: &userID,
301			Key:    storepb.UserSetting_SHORTCUTS,
302		})
303		if err != nil {
304			return nil, err
305		}
306		if userSetting == nil {
307			return nil, status.Errorf(codes.NotFound, "shortcut not found")
308		}
309	
310		shortcutsUserSetting := userSetting.GetShortcuts()
311		shortcuts := shortcutsUserSetting.GetShortcuts()
312		newShortcuts := make([]*storepb.ShortcutsUserSetting_Shortcut, 0, len(shortcuts))
313		found := false
314		for _, shortcut := range shortcuts {
315			if shortcut.GetId() != shortcutID {
316				newShortcuts = append(newShortcuts, shortcut)
317			} else {
318				found = true
319			}
320		}
321		if !found {
322			return nil, status.Errorf(codes.NotFound, "shortcut not found")
323		}
324		shortcutsUserSetting.Shortcuts = newShortcuts
325		userSetting.Value = &storepb.UserSetting_Shortcuts{
326			Shortcuts: shortcutsUserSetting,
327		}
328		_, err = s.Store.UpsertUserSetting(ctx, userSetting)
329		if err != nil {
330			return nil, status.Errorf(codes.Internal, "failed to upsert user setting: %v", err)
331		}
332	
333		return &emptypb.Empty{}, nil
334	}
